"""Batch 1 self-check: superseded tokens absent, repo-scoped names absent, required rules present."""
import re
import sys
from pathlib import Path

ROOT = Path("/home/usain/gov-os-worktrees/W2-11")
T = ROOT / "template/governance/kernel"
BRIEFS = sorted((T / "templates").glob("brief-*.md"))
SKILL = T / "skills/orchestration/SKILL.md"
REF = T / "skills/orchestration/briefs-and-returns.md"
AUDIT = T / "skills/audit/SKILL.md"
ROLE = T / "roles/orchestrator.md"

FORBIDDEN = [
    "LEAD_CHECKPOINT", "context limit", "DEC-508", "DEC-525", "names a held-out path", "<ceiling>",
    "ceiling", "no listing", "listing over", "W2-", "EXAMIN", "select_tests", "verify_lock", "disk_gate",
    "close_build", "gov-os-worktrees", "gov-os-workbench", "Dynamic-Agentic", "ROLES-SPEC", "ROLES-RESEARCH",
    "before implementation", "before the implementation", "Tests first", "tests first", "W1-",
]
FIELDS = ["task:", "status:", "work_completed:", "files_changed:", "evidence:", "tests:", "discoveries:",
          "risks:", "lessons:", "proposed_decisions:", "unresolved:", "recommended_next_action:"]
REQUIRED_ALL = ["Refused twice for the same call", "AUTH_REQUIRED", "DEC-820", "DEC-861", "Decided-by:",
                "twelve fields"]
fail = 0
for path in BRIEFS + [SKILL, REF, AUDIT, ROLE]:
    text = path.read_text()
    rel = path.relative_to(ROOT)
    for tok in FORBIDDEN:
        if tok in text:
            if path == ROLE and tok in ("W1-",):
                continue
            print(f"FORBIDDEN {tok!r} in {rel}")
            fail += 1
    if path in BRIEFS:
        if not text.startswith("---\n"):
            print(f"NO FRONTMATTER {rel}"); fail += 1
        for f in FIELDS:
            if not re.search(rf"^{re.escape(f)} ", text, re.M):
                print(f"MISSING FIELD {f} in {rel}"); fail += 1
        for r in REQUIRED_ALL + ["payload"]:
            if r not in text:
                print(f"MISSING {r!r} in {rel}"); fail += 1
        if re.search(r"`gov launch[^`]*`", text):
            print(f"LAUNCHER IN CODE SPAN {rel}"); fail += 1
    if path in (SKILL,):
        for r in REQUIRED_ALL + ["payload", "DEC-715", "DEC-731", "DEC-719", "DEC-732", "DEC-733", "DEC-847",
                                 "DEC-750", "DEC-754", "DEC-757 item 6", "DEC-766", "DEC-768 item 4", "DEC-779",
                                 "DEC-780", "DEC-787", "DEC-430", "DEC-959", "DEC-957"]:
            if r not in text:
                print(f"MISSING {r!r} in {rel}"); fail += 1
for path in [T / "templates/brief-reviewer.md", AUDIT]:
    text = path.read_text()
    for r in ['"Can an honest agent hit this in ordinary work?"', '"Does it fail open or lose work?"',
              "`Ordinary work: yes|no, because …`", "`Consequence: fails open|loses work|other`",
              'A finding marked "no" is a row, never a round', "threat-model record"]:
        if r not in text:
            print(f"MISSING judgement {r!r} in {path.relative_to(ROOT)}"); fail += 1
lead = (T / "templates/brief-lead.md").read_text()
if "brief_gaps:" not in lead:
    print("MISSING brief_gaps in lead"); fail += 1
print("FAILURES", fail)
sys.exit(1 if fail else 0)
